export function dateParts(value){const date=new Date(value);if(!value||!Number.isFinite(+date))return {valid:false};const parts=Object.fromEntries(new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(p=>[p.type,p.value]));return {...parts,time:`${parts.hour}:${parts.minute}`,valid:true}}
export function resultFor(m,id){if(m.status!=='finished')return '';const home=String(m.home.id)===String(id),diff=(m.home.score-m.away.score)*(home?1:-1);return diff>0?'승':diff<0?'패':'무'}
export function selectMatches(matches,now=Date.now()){const sorted=[...(matches||[])].sort((a,b)=>Date.parse(a.kickoff||a.date)-Date.parse(b.kickoff||b.date));return {upcoming:sorted.filter(m=>m.status==='live'||m.status==='scheduled'&&Date.parse(m.kickoff||m.date)>now-3*3600000).slice(0,3),recent:sorted.filter(m=>m.status==='finished').reverse().slice(0,2)}}
